from test_helpers import test, solo

test('Short unlisted helpful effect receives thanks',solo+"aura('player',999999,'Utility effect',5,5); auras.player[1].sourceUnit='target'; BuffTap:ObserveSoloThanks(); assert(#emotes==1 and emotes[1][2]=='target')")
test('Aura instance can be thanked without a readable spell ID',solo+"auras.player={{name='Helpful',spellId={secret=true},auraInstanceID=77,sourceUnit='target'}}; BuffTap:ObserveSoloThanks(); assert(#emotes==1)")
test('Thanks ignores casting cache and reads fresh indexed helpful auras',solo+"BuffTap.GetAuras=function() error('casting cache must not be used') end; C_UnitAuras.GetUnitAuras=function() error('batch reader must not be used') end; aura('player',1459,'Intellect'); auras.player[1].sourceUnit='target'; BuffTap:ObserveSoloThanks(); assert(#emotes==1)")
test('Player aura event captures provider before ordinary refresh',solo+"aura('player',1459,'Intellect'); auras.player[1].sourceUnit='target'; BuffTap.events.scripts.OnEvent(nil,'UNIT_AURA','player'); assert(#emotes==1); local old=UnitGUID; UnitGUID=function(u) return u=='target' and 'Player-Replaced' or old(u) end; advance(.2); assert(#emotes==1)")
test('Missing assist answer does not suppress verified foreign player',solo+"UnitCanAssist=function() return nil end; received(1459,'target'); assert(#emotes==1)")
test('Unknown self comparison is resolved by available player identity',solo+"UnitIsUnit=function() return nil end; received(1459,'target'); assert(#emotes==1)")
test('GUID self identity excludes player even if token comparison is unavailable',solo+"UnitIsUnit=function() return nil end; local old=UnitGUID; UnitGUID=function(u) return u=='target' and old('player') or old(u) end; received(1459,'target'); assert(#emotes==0)")
test('Live full name permits thanks when caster GUID is unavailable',solo+"local old=UnitGUID; UnitGUID=function(u) if u=='target' then return nil end return old(u) end; received(1459,'target'); assert(#emotes==1)")
test('Provider cooldown survives GUID becoming readable',solo+"local old=UnitGUID; UnitGUID=function(u) if u=='target' then return nil end return old(u) end; received(1459,'target'); UnitGUID=old; received(1243,'target'); assert(#emotes==1)")
test('Forever surname is captured with a space and emote uses unit token',solo+"local old=UnitName; UnitName=function(u) if u=='target' then return 'First','Surname' end return old(u) end; received(1459,'target'); assert(#emotes==1 and emotes[1][2]=='target' and BuffTap.helperThankCooldowns['name:First Surname'])")
test('Native false return is reported as emote requested',solo+"C_ChatInfo={PerformEmote=function(e,u) emotes[#emotes+1]={e,u}; return false end}; received(1459,'target'); assert(#emotes==1 and BuffTap.helperThankStatus:find('Thank emote requested',1,true))")
test('Native true return means restricted and is not retried',solo+"local n=0; C_ChatInfo={PerformEmote=function() n=n+1; return true end}; received(1459,'target'); advance(2); received(1243,'target'); assert(n==1 and BuffTap.helperThankStatus=='Client restricted the emote; no retry')")
test('Unreadable emote result is not called success or retried',solo+"local n=0; C_ChatInfo={PerformEmote=function() n=n+1; return {secret=true} end}; received(1459,'target'); advance(2); assert(n==1 and BuffTap.helperThankStatus:find('result restricted or unreadable',1,true))")
test('Throwing emote API reports call failure without automatic retry',solo+"local n=0; C_ChatInfo={PerformEmote=function() n=n+1; error('blocked') end}; received(1459,'target'); advance(2); assert(n==1 and BuffTap.helperThankStatus=='Emote call failed; no retry')")
test('Missing source diagnostics identifies spell and rejection gate',solo+"auras.player={{spellId=1459,auraInstanceID=42,name='Buff'}}; BuffTap:ObserveSoloThanks(); assert(BuffTap.helperThankStatus:find('source unit missing or restricted',1,true) and BuffTap.helperThankStatus:find('spell 1459, instance 42',1,true))")
test('Missing caster unit produces a specific reason',solo+"local old=UnitExists; UnitExists=function(u) return u~='target' and old(u) end; received(1459,'target'); assert(#emotes==0 and BuffTap.helperThankStatus:find('caster unit unavailable: target',1,true))")
test('Unreadable caster player type produces a specific reason',solo+"UnitIsPlayer=function() return nil end; received(1459,'target'); assert(#emotes==0 and BuffTap.helperThankStatus:find('caster player identity unavailable',1,true))")
test('Missing caster name produces a specific reason',solo+"local old=UnitName; UnitName=function(u) if u=='target' then return nil end return old(u) end; GetUnitName=nil; received(1459,'target'); assert(#emotes==0 and BuffTap.helperThankStatus:find('caster name unavailable: target',1,true))")
test('NPC buffs do not trigger thanks or an unidentified-player error',solo+"UnitIsPlayer=function(u) return u~='target' end; received(1459,'target'); assert(#emotes==0 and not BuffTap.helperThankStatus:find('caster unavailable',1,true))")
test('Helpful reader preserves existing baseline across unreadable slots',solo+"received(1459,'target'); local old=C_UnitAuras.GetAuraDataByIndex; C_UnitAuras.GetAuraDataByIndex=function(u,i) if i==1 then return {secret=true} end return old(u,i) end; BuffTap:ObserveSoloThanks(); assert(BuffTap.helperThankSeen and next(BuffTap.helperThankSeen))")
test('Refresh after immediate aura capture does not double thank',solo+"aura('player',1459,'Intellect'); auras.player[1].sourceUnit='target'; BuffTap.events.scripts.OnEvent(nil,'UNIT_AURA','player'); advance(.2); assert(#emotes==1)")
